def group_by_key(data: list[dict], key: str) -> dict:
    """Groups a list of dictionaries by the value of a given key.

    Args:
        data: List of dictionaries to group.
        key: The key to group by.

    Returns:
        A dictionary where keys are unique values of the given key and values are lists of dictionaries.

    Raises:
        ValueError: If the key is not present in any dictionary.

    Example:
        >>> data = [{'category': 'A', 'value': 1}, {'category': 'B', 'value': 2}, {'category': 'A', 'value': 3}]
        >>> group_by_key(data, 'category')
        {'A': [{'category': 'A', 'value': 1}, {'category': 'A', 'value': 3}], 'B': [{'category': 'B', 'value': 2}]}
    """
    if not data:
        return {}

    result = {}
    for item in data:
        if key not in item:
            raise ValueError(f"Key '{key}' not found in dictionary {item}")
        value = item[key]
        if value not in result:
            result[value] = []
        result[value].append(item)

    return result

